head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil25400";

///////// 2. 초기화 영역 /////////
// [A] 초기 목록 미해결 — 진입 근거가 다른 액션을 가리킨다(popnote vs note) — 어느 쪽인지 정할 근거가 없다

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.form_noteForm = { action: "", method: 'post', target: '' };

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil25400.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name listTable_oncellclick
 * @description listTable 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listTable_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_noteList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_noteList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        await scwin.viewContents(r["notiSvcId"], r["notiSeq"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'listTable.oncellclick' });
    }
};

/**
 * @method
 * @name divContn_cell_onclick
 * @description divContn_cell 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.divContn_cell_onclick = function(e){
    try {
        scwin.viewClose()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil25400.divContn_cell_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Delete
 * @description Delete 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Delete = async function () {
    const sbmOptions = {
        id: "tx_fn_Delete",
        method: "post",
        action: "/account/note.do",
        ref: "dma_DeleteReq",
        target: "dlt_noteList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_ViewContents_xhr
 * @description View Contents xhr 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_ViewContents_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_ViewContents_xhr"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_ViewContents_xhr", unresolved: "action:self_submit:tx_fn_ViewContents_xhr" };
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name listTable_fmt_column1
 * @description list Table fmt column1 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listTable_fmt_column1 = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_noteList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "readYn") ?? '') : '');
        if (v === 'Y') { return (console.error('[sdd] 미실현 라벨 갈래: column1 (image)'), String(data ?? '')); }
        return (console.error('[sdd] 미실현 라벨 갈래: column1 (image)'), String(data ?? ''));
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "listTable.column1" }); return String(data ?? ''); }
};

/**
 * @method
 * @name viewContents
 * @description view Contents 처리
 * @param {String} _notiSvcId _notiSvcId
 * @param {*} _notiSeq _notiSeq
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.viewContents = async function (_notiSvcId, _notiSeq) {
    $c.util.getComponent('dma_DeleteReq').set('notiSvcId', _notiSvcId);
    $c.util.getComponent('dma_DeleteReq').set('notiSeq', _notiSeq);
    scwin.form_noteForm.action = "/account/popNote.do";
    $c.util.getComponent('dma_DeleteReq').set('method', "noteDetail");
    await scwin.tx_fn_ViewContents_xhr();
};

/**
 * @method
 * @name deleteDeleteReq
 * @description delete Delete Req 처리
 * @param {String} _notiSvcId _notiSvcId
 * @param {*} _notiSeq _notiSeq
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.deleteDeleteReq = async function (_notiSvcId, _notiSeq) {
    $c.util.getComponent('dma_DeleteReq').set('notiSvcId', _notiSvcId);
    $c.util.getComponent('dma_DeleteReq').set('notiSeq', _notiSeq);
    $c.util.getComponent('dma_DeleteReq').set('method', "deleteNote");
    await scwin.tx_fn_Delete();
};

/**
 * @method
 * @name onCompleteResponse
 * @description on Complete Response 처리
 * @param {*} responseText responseText
 * @returns {void}
 * @hidden N
 */
scwin.onCompleteResponse = function (responseText) {
    const viewDiv = $c.util.getComponent('txt_divContn');
    (!viewDiv ? console.warn('[sdd] 표시 전환 대상 미해결: viewDiv') : (('inline') === 'none' ? (viewDiv.hide ? viewDiv.hide() : void 0) : (viewDiv.show ? viewDiv.show() : void 0)));
    viewDiv.setStyle('left', $c.util.getComponent('listTable').getBoundingClientRect().left + 105);
    viewDiv.setStyle('top', document.body.scrollTop + event.clientY + 10);
    viewDiv.innerHTML = responseText;
};

/**
 * @method
 * @name viewClose
 * @description view Close 처리
 * @returns {void}
 * @hidden N
 */
scwin.viewClose = function () {
    const viewDiv = $c.util.getComponent('txt_divContn');
    (!viewDiv ? console.warn('[sdd] 표시 전환 대상 미해결: viewDiv') : (('none') === 'none' ? (viewDiv.hide ? viewDiv.hide() : void 0) : (viewDiv.show ? viewDiv.show() : void 0)));
};
